 private final PurchaseService service=new PurchaseService();private final SupportApiClient support=new SupportApiClient();private final FxDebouncer searchDebouncer=new FxDebouncer(java.time.Duration.ofMillis(220));private final NumberFormat money=NumberFormat.getCurrencyInstance(Locale.of("en", "IN"));private final Map<Integer,Boolean>whatsappState=new HashMap<>();private List<Purchase>all=List.of(),filtered=List.of();private Purchase selected;private int currentPage;
 @FXML public void initialize(){
        if(purchasePageIcon!=null)purchasePageIcon.getChildren().setAll(IconFactory.icon("purchase",24));installKpiIcons();configureExplicitTableHeaderIcons();applyRangeButtonIcons();configureExplicitButtonIcons();configureDetailsCloseButton();colInvoice.setCellValueFactory(v->new SimpleStringProperty(v.getValue().getInvoiceNo()));colDate.setCellValueFactory(v->new SimpleStringProperty(v.getValue().getInvoiceDate().toString()));colSupplier.setCellValueFactory(v->new SimpleStringProperty(v.getValue().getSupplier().getName()));colMobile.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().getSupplier().getPhone())));colAmount.setCellValueFactory(v->new SimpleDoubleProperty(v.getValue().getTotalAmount()).asObject());colPaid.setCellValueFactory(v->new SimpleDoubleProperty(v.getValue().getPaidAmount()).asObject());colBalance.setCellValueFactory(v->new SimpleDoubleProperty(v.getValue().getBalanceAmount()).asObject());colDue.setCellValueFactory(v->new SimpleStringProperty(due(v.getValue())));colStatus.setCellValueFactory(v->new SimpleStringProperty(v.getValue().getPaymentStatus()));colMail.setCellValueFactory(v->new SimpleStringProperty(v.getValue().isEmailSent()?"Sent":"Not Sent"));colAmount.setCellFactory(x->totalMoneyCell());colPaid.setCellFactory(x->paidMoneyCell());colBalance.setCellFactory(x->balanceMoneyCell());colStatus.setCellFactory(x->pill());colMail.setCellFactory(x->pill());setupActions();cmbPaymentStatus.getItems().setAll("All","PENDING","PARTIAL","PAID","OVERDUE");cmbPaymentStatus.setValue("All");cmbMailStatus.getItems().setAll("All","Sent","Not Sent");cmbMailStatus.setValue("All");cmbSupplier.getItems().setAll("All Suppliers");cmbSupplier.setValue("All Suppliers");cmbPageSize.getItems().setAll(10,25,50,100);cmbPageSize.setValue(25);cmbPageSize.valueProperty().addListener((o,a,b)->{currentPage=0;renderPage();});dpFrom.setValue(null);dpTo.setValue(null);txtSearch.textProperty().addListener((o,a,b)->searchDebouncer.submit(this::filter));cmbSupplier.valueProperty().addListener((o,a,b)->filter());cmbPaymentStatus.valueProperty().addListener((o,a,b)->filter());cmbMailStatus.valueProperty().addListener((o,a,b)->filter());tablePurchase.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null)details(b);});detailDrawer.setManaged(false);detailDrawer.setVisible(false);mainSplit.setDividerPositions(1);refresh();configureModernTable();installRegisterTools();}

