 private void setKpiIcon(StackPane pane,String semantic){if(pane!=null)pane.getChildren().setAll(IconFactory.compactIcon(semantic,22));}

 private TableCell<Purchase,Double> moneyCell(){return new TableCell<>(){protected void updateItem(Double v,boolean e){super.updateItem(v,e);setText(e||v==null?null:fmt(v));setAlignment(Pos.CENTER_RIGHT);}};}
 private TableCell<Purchase,Double> totalMoneyCell(){return coloredMoneyCell("register-total-amount",null);}
 private TableCell<Purchase,Double> balanceMoneyCell(){return coloredMoneyCell("register-balance-pending","register-balance-settled");}
 private TableCell<Purchase,Double> coloredMoneyCell(String positiveClass,String zeroClass){return new TableCell<>(){protected void updateItem(Double v,boolean e){super.updateItem(v,e);setText(e||v==null?null:fmt(v));setAlignment(Pos.CENTER_RIGHT);getStyleClass().removeAll("register-total-amount","register-balance-pending","register-balance-settled");if(!e&&v!=null){String style=v>.009?positiveClass:zeroClass;if(style!=null)getStyleClass().add(style);}}};}
 private TableCell<Purchase,Double> paidMoneyCell(){return new TableCell<>(){protected void updateItem(Double v,boolean e){super.updateItem(v,e);setText(e||v==null?null:fmt(v));setAlignment(Pos.CENTER_RIGHT);getStyleClass().removeAll("purchase-paid-positive","purchase-paid-zero");if(!e&&v!=null)getStyleClass().add(v>.009?"purchase-paid-positive":"purchase-paid-zero");}};}
